import type { NextRequest } from 'next/server'

/**
 * JWT Authentication Middleware for Next.js
 * 
 * This middleware checks for a valid JWT token in cookies and redirects
 * unauthenticated users to the login page. It excludes certain paths
 * like login, register, and static assets from authentication checks.
 */

interface JWTPayload {
  userId: string
  email?: string
  role?: string
  exp?: number
  iat?: number
}

/**
 * Verify JWT token
 * In a real application, you would use a proper JWT library like jsonwebtoken
 * or jose to verify the token signature and expiration
 */
function verifyJWT(token: string): JWTPayload | null {
  try {
    // Split the JWT into its parts
    const parts = token.split('.')
    if (parts.length !== 3) {
      return null
    }

    // Decode the payload (second part)
    const payload = JSON.parse(atob(parts[1]))

    // Check if token is expired
    if (payload.exp && payload.exp * 1000 < Date.now()) {
      return null
    }

    return payload
  } catch (error) {
    console.error('JWT verification failed:', error)
    return null
  }
}

/**
 * Check if the request has a valid authentication token
 */
function isAuthenticated(request: NextRequest): boolean {
  try {
    // Get the JWT token from cookies
    const token = request.cookies.get('auth-token')?.value

    if (!token) {
      return false
    }

    // Verify the JWT token
    const payload = verifyJWT(token)

    if (!payload) {
      return false
    }

    // Additional validation can be added here
    // For example, check if the user exists in your database

    return true
  } catch (error) {
    console.error('Authentication check failed:', error)
    return false
  }
}

/**
 * Main middleware function
 */
export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl

  // Define public paths that don't require authentication
  const publicPaths = [
    '/login',
    '/register', 
    '/forgot-password',
    '/reset-password',
    '/api/auth',
    '/_next',
